    {
        class Key
        {
            public List<Panel> Panels;
            public double Tolerance;

            public bool Matches(Key o) => o != null && Tolerance == o.Tolerance
                && Panels.Count == o.Panels.Count && Panels.Zip(o.Panels, ReferenceEquals).All(x => x);
        }

        class Result
        {
            public List<int> Groups = new List<int>();
            public List<Panel> Representatives = new List<Panel>();
        }

        readonly object _lock = new object();
        CancellationTokenSource _cts;
        Key _runningKey;
        Key _doneKey;
        Result _result;
        int _progress;

        public GroupIdenticalPanelsComponent()
            : base("Group Identical Panels", "Group", "Groups panels with matching dimensions", "Fabrication") { }

        public override Guid ComponentGuid => new Guid("6cbe8f65-7192-4dda-bce6-5ce8a017d346");

        protected override void RegisterInputParams(GH_InputParamManager pManager)
        {
            AddPanelInput(pManager, "Panels", "P", "Panels", GH_ParamAccess.list);
            pManager.AddNumberParameter("Tolerance", "T", "Maximum length difference", GH_ParamAccess.item, 1.0);
        }

        protected override void RegisterOutputParams(GH_OutputParamManager pManager)
        {
            pManager.AddIntegerParameter("Group", "G", "Group number per panel", GH_ParamAccess.list);
            pManager.AddIntegerParameter("Group Count", "N", "Number of groups", GH_ParamAccess.item);
            AddPanelOutput(pManager, "Representatives", "R", "First panel of each group", GH_ParamAccess.list);
        }

        static double[] Signature(Panel p)
        {
            var e = p.EdgeLengths(); Array.Sort(e);
            var d = p.DiagonalLengths(); Array.Sort(d);
            return e.Concat(d).ToArray();
        }

        protected override void SolveInstance(IGH_DataAccess DA)
        {
            var panels = GetPanels(DA, 0);
            double tol = 1.0;
            if (panels == null || !DA.GetData(1, ref tol))
            {
                Cancel();
                return;
            }
            if (tol <= 0)
            {
                Cancel();
                AddRuntimeMessage(GH_RuntimeMessageLevel.Error, "Tolerance must be greater than 0.");
                return;
            }
            var key = new Key { Panels = panels, Tolerance = tol };

            Result ready = null;
            lock (_lock)
            {
                if (_result != null && key.Matches(_doneKey)) ready = _result;
                else if (_runningKey != null && key.Matches(_runningKey))
                {
                    Message = _progress + "%";
                    return;
                }
            }

            if (ready == null)
            {
                Start(key);
                return;
            }

            Message = "";
            DA.SetDataList(0, ready.Groups);
            DA.SetData(1, ready.Representatives.Count);
            DA.SetDataList(2, ready.Representatives.Select(p => new GH_Panel(p)));
        }

        void Cancel()
        {
            lock (_lock)
            {
                _cts?.Cancel();
                _cts = null;
                _runningKey = null;
                _doneKey = null;
                _result = null;
            }
            Message = "";
        }

        void Start(Key key)
        {
            CancellationTokenSource cts;
            lock (_lock)
            {
                _cts?.Cancel();
                _cts = cts = new CancellationTokenSource();
                _runningKey = key;
                _doneKey = null;
                _result = null;
                _progress = 0;
            }
            Message = "0%";

            Task.Run(() =>
            {
                Result result;
                try { result = Group(key, cts.Token); }
                catch (OperationCanceledException) { return; }
                catch (Exception) { result = new Result(); }

                lock (_lock)
                {
                    if (cts.IsCancellationRequested) return;
                    _runningKey = null;
                    _doneKey = key;
                    _result = result;
                }
                RhinoApp.InvokeOnUiThread(new Action(() =>
                {
                    if (!cts.IsCancellationRequested) ExpireSolution(true);
                }));
            });
        }

        void ReportProgress(int percent, CancellationToken token)
        {
            if (percent == _progress) return;
            _progress = percent;
            RhinoApp.InvokeOnUiThread(new Action(() =>
            {
                if (token.IsCancellationRequested) return;
                Message = percent + "%";
                OnDisplayExpired(false);
            }));
        }

        Result Group(Key key, CancellationToken token)
        {
            double tol = key.Tolerance;
            var sigs = new List<double[]>();
            var result = new Result();
            for (int n = 0; n < key.Panels.Count; n++)
            {
                token.ThrowIfCancellationRequested();
                ReportProgress(100 * n / Math.Max(1, key.Panels.Count), token);

                var p = key.Panels[n];
                var s = Signature(p);
                int g = sigs.FindIndex(r => r.Zip(s, (a, b) => Math.Abs(a - b) <= tol).All(x => x));
                if (g < 0)
                {
                    g = sigs.Count;
                    sigs.Add(s);
                    result.Representatives.Add(p);
                }
                result.Groups.Add(g);
            }
            return result;
        }

        public override void RemovedFromDocument(GH_Document document)
        {
            Cancel();
            base.RemovedFromDocument(document);
        }
    }

